import{_ as a,H as n,f as e,i as p}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"28 | test::nginx 还可以这样用？","description":"","frontmatter":{},"headers":[{"level":2,"title":"测试中的调试","slug":"测试中的调试","link":"#测试中的调试","children":[{"level":3,"title":"ONLY","slug":"only","link":"#only","children":[]},{"level":3,"title":"SKIP","slug":"skip","link":"#skip","children":[]},{"level":3,"title":"LAST","slug":"last","link":"#last","children":[]}]},{"level":2,"title":"测试计划 plan","slug":"测试计划-plan","link":"#测试计划-plan","children":[]},{"level":2,"title":"预处理器","slug":"预处理器","link":"#预处理器","children":[]},{"level":2,"title":"自定义函数","slug":"自定义函数","link":"#自定义函数","children":[]},{"level":2,"title":"乱序","slug":"乱序","link":"#乱序","children":[]},{"level":2,"title":"reindex","slug":"reindex","link":"#reindex","children":[]},{"level":2,"title":"写在最后","slug":"写在最后","link":"#写在最后","children":[]}],"relativePath":"OpenResty从入门到实战/28-test-nginx还可以这样用？.md","filePath":"OpenResty从入门到实战/28-test-nginx还可以这样用？.md","lastUpdated":1779816093000}'),l={name:"OpenResty从入门到实战/28-test-nginx还可以这样用？.md"};function t(i,s,c,o,d,r){return n(),e("div",null,[...s[0]||(s[0]=[p(`<h1 id="_28-test-nginx-还可以这样用" tabindex="-1">28 | test::nginx 还可以这样用？ <a class="header-anchor" href="#_28-test-nginx-还可以这样用" aria-label="Permalink to &quot;28 | test::nginx 还可以这样用？&quot;">​</a></h1><p>你好，我是温铭。</p><p>在前面两个章节中，你已经掌握了 <code>test::nginx</code> 的大部分使用方法，我相信你已经能够看明白 OpenResty 项目中大部分的测试案例集了。这对于学习 OpenResty 和它的周边库而言，已经足够了。</p><p>但如果你有志于成为 OpenResty 的代码贡献者，或者你正在自己的项目中使用 <code>test::nginx</code> 来编写测试案例，那么你还需要来学习一些更高级、更复杂的用法。</p><p>今天的内容，可能会是这个专栏中最“高冷”的部分，因为这都是从来没有人分享过的内容。 以 lua-nginx-module 这个 OpenResty 中最核心的模块为例，全球一共有 70 多个贡献者，但并非每个贡献者都写过测试案例。所以，如果学完今天的课程，你在 <code>test::nginx</code> 上的理解，绝对可以进入全球 Top 100。</p><h2 id="测试中的调试" tabindex="-1">测试中的调试 <a class="header-anchor" href="#测试中的调试" aria-label="Permalink to &quot;测试中的调试&quot;">​</a></h2><p>首先，我们来看几个最简单、也是开发者最常用到的原语，它们在平时的调试中会被使用到。下面，我们就来依次介绍下，这几个调试相关的原语的使用场景。</p><h3 id="only" tabindex="-1">ONLY <a class="header-anchor" href="#only" aria-label="Permalink to &quot;ONLY&quot;">​</a></h3><p>很多时候，我们都是在原有的测试案例集基础上，新增了一个测试案例。如果这个测试文件包含了很多的测试案例，那么从头到尾跑一遍显然是比较耗时的，这在你需要反复修改测试案例的时候尤为明显。</p><p>那么，有没有什么方法只运行你指定的某一个测试案例呢？ <code>ONLY</code> 这个标记可以轻松实现这一点：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=== TEST 1: sanity</span></span>
<span class="line"><span>=== TEST 2: get</span></span>
<span class="line"><span>--- ONLY</span></span></code></pre></div><p>上面这段伪码就展示了如何使用这个原语。把 <code>--- ONLY</code> 放在需要单独运行的测试案例的最后一行，那么使用 prove 来运行这个测试案例文件的时候，就会忽略其他所有的测试案例，只运行这一个测试了。</p><p>不过，这只适合在你做调试的时候使用。所以， prove 命令发现 ONLY 标记的时候，也会给出提示，告诉你不要忘记在提交代码时把它去掉。</p><h3 id="skip" tabindex="-1">SKIP <a class="header-anchor" href="#skip" aria-label="Permalink to &quot;SKIP&quot;">​</a></h3><p>与只执行一个测试案例对应的需求，就是忽略掉某一个测试案例。 <code>SKIP</code> 这个标记，一般用于测试尚未实现的功能：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=== TEST 1: sanity</span></span>
<span class="line"><span>=== TEST 2: get</span></span>
<span class="line"><span>--- SKIP</span></span></code></pre></div><p>从这段伪码你可以看到，它的用法和ONLY类似。因为我们是测试驱动开发，需要先编写测试案例；而在集体编码实现时，可能由于实现难度或者优先级的关系，导致某个功能需要延后实现。那么这时候，你就可以先跳过对应的测试案例集，等实现完成后，再把 SKIP 标记去掉即可。</p><h3 id="last" tabindex="-1">LAST <a class="header-anchor" href="#last" aria-label="Permalink to &quot;LAST&quot;">​</a></h3><p>还有一个常用的标记是 <code>LAST</code>，它的用法也很简单，在它之前的测试案例集都会被执行，后面的就会被忽略掉：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=== TEST 1: sanity</span></span>
<span class="line"><span>=== TEST 2: get</span></span>
<span class="line"><span>--- LAST</span></span>
<span class="line"><span>=== TEST 3: set</span></span></code></pre></div><p>你可能疑惑，ONLY和SKIP我能理解，但LAST这个功能有什么用呢？实际上，有时候你的测试案例是有依赖关系的，需要你执行完前面几个测试案例后，之后的测试才有意义。那么，在这种情况下去调试的话，LAST 就非常有用了。</p><h2 id="测试计划-plan" tabindex="-1">测试计划 plan <a class="header-anchor" href="#测试计划-plan" aria-label="Permalink to &quot;测试计划 plan&quot;">​</a></h2><p>在 <code>test::nginx</code> 所有的原语中， <code>plan</code> 是最容易让人抓狂、也是最难理解的一个。它源自于 perl 的 <code>Test::Plan</code> 模块，所以文档并不在 <code>test::nginx</code> 中，找到它的解释并不容易，所以我把它放在靠前的位置来介绍。我见过好几个 OpenResty 的代码贡献者，都在这个坑里面跌倒，甚至爬不出来。</p><p>下面是一个示例，在 OpenResty 官方测试集的每一个文件的开始部分，你都能看到类似的配置：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>plan tests =&amp;gt; repeat_each() * (3 * blocks());</span></span></code></pre></div><p>这里 plan 的含义是，在整个测试文件中，按照计划应该会做多少次检测项。如果最终运行的结果和计划不符，整个测试就会失败。</p><p>拿这个示例来说，如果 <code>repeat_each</code> 的值是 2，一共有 10 个测试案例，那么 plan 的值就应该是2 x 3 x 10 = 60。这里估计你唯一搞不清楚的，就是数字 3 的含义吧，看上去完全是一个 magic number！</p><p>别着急，我们继续看示例，一会儿你就能搞懂了。先来说说，你能算清楚下面这个测试案例中，plan 的正确值是多少吗？</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=== TEST 1: sanity</span></span>
<span class="line"><span>--- config</span></span>
<span class="line"><span>    location /t {</span></span>
<span class="line"><span>        content_by_lua_block {</span></span>
<span class="line"><span>            ngx.say(&quot;hello&quot;)</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>--- request</span></span>
<span class="line"><span>GET /t</span></span>
<span class="line"><span>--- response_body</span></span>
<span class="line"><span>hello</span></span></code></pre></div><p>我相信所有人都会得出 plan = 1 的结论，因为测试中只对 <code>response_body</code> 进行了校验。</p><p>但，事实并非如此！正确的答案是， plan = 2。为什么呢？因为 <code>test::nginx</code> 中隐含了一个校验，也就是 <code>--- error_code: 200</code>，它默认检测 HTTP 的 response code 是否为 200。</p><p>所以，上面的 magic number 3，真实含义是在每一个测试中都显式地检测了两次，比如 body 和 error log；同时，隐式地检测了 response code。</p><p>由于这个地方太容易出错，所以，我的建议是，推荐你用下面的方法，直接关闭掉 plan：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use Test::Nginx::Socket &#39;no_plan&#39;;</span></span></code></pre></div><p>如果无法关闭，比如在 OpenResty 的官方测试集中遇到 plan 不准确的情况，建议你也不要去深究原因，直接在 plan 的表达式中增加或者减少数字即可：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>plan tests =&amp;gt; repeat_each() * (3 * blocks()) + 2;</span></span></code></pre></div><p>这也是官方会使用到的方法。</p><h2 id="预处理器" tabindex="-1">预处理器 <a class="header-anchor" href="#预处理器" aria-label="Permalink to &quot;预处理器&quot;">​</a></h2><p>我们知道，在同一个测试文件的不同测试案例之间，可能会有一些共同的设置。如果在每一个测试案例中都重复设置，就会让代码显得冗余，后面修改起来也比较麻烦。</p><p>这时候，你就可以使用 <code>add_block_preprocessor</code> 指令，来增加一段 perl 代码，比如下面这样来写：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>add_block_preprocessor(sub {</span></span>
<span class="line"><span>    my $block = shift;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    if (!defined $block-&amp;gt;config) {</span></span>
<span class="line"><span>        $block-&amp;gt;set_value(&quot;config&quot;, &amp;lt;&amp;lt;&#39;_END_&#39;);</span></span>
<span class="line"><span>    location = /t {</span></span>
<span class="line"><span>        echo $arg_a;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    _END_</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>});</span></span></code></pre></div><p>这个预处理器，就会为所有的测试案例，都增加一段 config 的配置，而里面的内容就是 <code>location /t</code>。这样，在你后面的测试案例里，就都可以省略掉 config，直接访问即可：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=== TEST 1:</span></span>
<span class="line"><span>--- request</span></span>
<span class="line"><span>    GET /t?a=3</span></span>
<span class="line"><span>--- response_body</span></span>
<span class="line"><span>3</span></span>
<span class="line"><span></span></span>
<span class="line"><span>=== TEST 2:</span></span>
<span class="line"><span>--- request</span></span>
<span class="line"><span>    GET /t?a=blah</span></span>
<span class="line"><span>--- response_body</span></span>
<span class="line"><span>blah</span></span></code></pre></div><h2 id="自定义函数" tabindex="-1">自定义函数 <a class="header-anchor" href="#自定义函数" aria-label="Permalink to &quot;自定义函数&quot;">​</a></h2><p>除了在预处理器中增加 perl 代码之外，你还可以在 <code>run_tests</code> 原语之前，随意地增加 perl 函数，也就是我们所说的自定义函数。</p><p>下面是一个示例，它增加了一个读取文件的函数，并结合 <code>eval</code> 指令，一起实现了 POST 文件的功能：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sub read_file {</span></span>
<span class="line"><span>    my $infile = shift;</span></span>
<span class="line"><span>    open my $in, $infile</span></span>
<span class="line"><span>        or die &quot;cannot open $infile for reading: $!&quot;;</span></span>
<span class="line"><span>    my $content = do { local $/; &amp;lt;$in&amp;gt; };</span></span>
<span class="line"><span>    close $in;</span></span>
<span class="line"><span>    $content;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>our $CONTENT = read_file(&quot;t/test.jpg&quot;);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>run_tests;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>__DATA__</span></span>
<span class="line"><span></span></span>
<span class="line"><span>=== TEST 1: sanity</span></span>
<span class="line"><span>--- request eval</span></span>
<span class="line"><span>&quot;POST /\\n$::CONTENT&quot;</span></span></code></pre></div><h2 id="乱序" tabindex="-1">乱序 <a class="header-anchor" href="#乱序" aria-label="Permalink to &quot;乱序&quot;">​</a></h2><p>除了上面几点外， <code>test::nginx</code> 还有一个鲜为人知的坑：默认乱序、随机来执行测试案例，而非按照测试案例的前后顺序和编号来执行。</p><p>它的初衷是想测试出更多的问题。毕竟，每一个测试案例运行完后，都会关闭 Nginx 进程，并启动新的 Nginx 来执行，结果不应该和顺序相关才对。</p><p>对于底层的项目而言，确实如此。但是，对于应用层的项目来说，外部存在数据库等持久化存储。这时候的乱序执行，就会导致错误的结果。由于每次都是随机的，所以可能报错，也可能不报错，每次的报错还可能不同。这显然会给开发者带来困惑，就连我都在这里跌倒过好多次。</p><p>所以，我的忠告就是：请关闭掉这个特性。你可以用下面这两行代码来关闭：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>no_shuffle();</span></span>
<span class="line"><span>run_tests;</span></span></code></pre></div><p>其中， <code>no_shuffle</code> 原语就是用来禁用随机，让测试严格按照测试案例的前后顺序来运行。</p><h2 id="reindex" tabindex="-1">reindex <a class="header-anchor" href="#reindex" aria-label="Permalink to &quot;reindex&quot;">​</a></h2><p>最后，让我们聊一个不烧脑的、轻松一点儿的话题。OpenResty 的测试案例集，对格式有着严格的要求。每个测试案例之间都需要有 3 个换行来分割，测试案例的编号也要严格保持自增长。</p><p>幸好，我们有对应的自动化工具 <code>reindex</code> 来做这些繁琐的事情，它隐藏在 <a href="https://github.com/openresty/openresty-devel-utils" target="_blank" rel="noreferrer">[ openresty-devel-utils]</a> 项目中，因为没有文档来介绍，知道的人很少。</p><p>有兴趣的同学，可以尝试着把测试案例的编号打乱，或者增删分割的换行个数，然后用这个工具来整理下，看看是否可以还原。</p><h2 id="写在最后" tabindex="-1">写在最后 <a class="header-anchor" href="#写在最后" aria-label="Permalink to &quot;写在最后&quot;">​</a></h2><p>关于 <code>test::nginx</code> 的介绍就到此结束了。当然，它的功能其实还有更多，我们只讲了最核心最重要的一些。授人以鱼不如授人以渔，学习测试的基本方法和注意点我都已经教给你了，剩下的就需要你自己去官方的测试案例集中去挖掘了。</p><p>最后给你留一个问题。在你的项目开发中，是否有测试？你又是使用什么框架来测试的呢？欢迎留言和我交流这个问题，也欢迎你把这篇文章分享给更多的人，一起交流和学习。</p>`,61)])])}const g=a(l,[["render",t]]);export{u as __pageData,g as default};
